#!/usr/bin/env bash
# Apply the CrossFile Android shell patches to the generated Tauri Android project.
#
#   apps/mobile/android-extras/apply.sh
#
# The Tauri Android project under `src-tauri/gen/android/` is generated by
# `tauri android init`. If it is ever regenerated (new Tauri CLI template), run
# this script again to restore the shell behaviour. Idempotent.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
android="$here/../src-tauri/gen/android"
pkg_dir="$android/app/src/main/java/com/crossfile/mobile"
manifest="$android/app/src/main/AndroidManifest.xml"

if [ ! -d "$android" ]; then
  echo "error: $android not found; run 'tauri android init' first (docs/mobile.md §2)" >&2
  exit 1
fi

mkdir -p "$pkg_dir"
cp "$here/kotlin/MainActivity.kt" "$pkg_dir/MainActivity.kt"
cp "$here/kotlin/KeepAliveService.kt" "$pkg_dir/KeepAliveService.kt"
cp "$here/kotlin/ShareIntake.kt" "$pkg_dir/ShareIntake.kt"

python3 - "$manifest" <<'PY'
import sys
import re

path = sys.argv[1]
with open(path, encoding="utf-8") as fh:
    xml = fh.read()

changed = False

# 1. Permissions (foreground service + wake lock + notification on 13+).
permissions = [
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_DATA_SYNC",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.WAKE_LOCK",
]
anchor = '<uses-permission android:name="android.permission.INTERNET" />'
if anchor in xml:
    missing = [p for p in permissions if f'android:name="{p}"' not in xml]
    if missing:
        block = "\n".join(f'    <uses-permission android:name="{p}" />' for p in missing)
        xml = xml.replace(anchor, anchor + "\n" + block, 1)
        changed = True
else:
    print("warning: INTERNET permission anchor not found; manifest permissions not patched", file=sys.stderr)

# 2. Foreground service declaration inside <application>.
if "KeepAliveService" not in xml:
    service = '''
        <service
            android:name=".KeepAliveService"
            android:exported="false"
            android:foregroundServiceType="dataSync" />'''
    xml = xml.replace("</application>", service + "\n    </application>", 1)
    changed = True

# 3. ACTION_SEND intent filter on MainActivity (share panel intake).
if "android.intent.action.SEND" not in xml:
    match = re.search(r'<activity\b[^>]*android:name="\.MainActivity"[^>]*>', xml)
    if match:
        end = xml.find("</activity>", match.end())
        if end != -1:
            intent_filter = '''
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="*/*" />
            </intent-filter>'''
            xml = xml[:end] + intent_filter + "\n        " + xml[end:]
            changed = True
    if not match:
        print("warning: MainActivity not found; ACTION_SEND filter not patched", file=sys.stderr)

if changed:
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(xml)
    print(f"patched {path}")
else:
    print(f"already patched {path}")
PY

echo "android shell patches applied: $(basename "$pkg_dir")/{MainActivity,KeepAliveService,ShareIntake}.kt + manifest"
